const B=window.BRAND,D=window.CATALOGUE,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={mode:'reviewed',query:'',category:'All',types:[],sort:'editorial',savedOnly:false,saved:[],compare:[],drafts:[]};
try{state.saved=JSON.parse(localStorage.getItem(B.id+'-saved')||'[]');state.drafts=JSON.parse(localStorage.getItem(B.id+'-drafts')||'[]');if(!Array.isArray(state.saved))state.saved=[];if(!Array.isArray(state.drafts))state.drafts=[];}catch(e){}
const views=[['discover','Discover'],['products','Product / Service'],['technical','Skill / MCP / Repo'],['marketplace','Marketplace / Partners']];
const routes=['discover','categories','products','technical','skills','mcp-servers','plugins','repositories','partners','marketplace','submit','about','how-listings-work','provenance-and-licences','security-and-installation-safety','terms','privacy','contact','saved','review','sitemap',...B.extra.map(x=>x[0])];
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4000);}
function persist(){try{localStorage.setItem(B.id+'-saved',JSON.stringify(state.saved));localStorage.setItem(B.id+'-drafts',JSON.stringify(state.drafts));}catch(e){toast('Browser storage is unavailable. Export your review notes to keep them.');}}
function download(name,content){const u=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
const pool=()=>D.filter(d=>state.mode==='demo'?d.demo:!d.demo);
const href=d=>'#/item/'+d.id;
const technical=d=>['Repository','MCP Server','Skill','Plugin','Connector'].includes(d.type);
function external(url,label,cls=''){return /^https:\/\//.test(url||'')?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer" class="${cls}">${label} ↗<span class="sr-only"> (opens in a new tab)</span></a>`:'';}
function badge(text,cls=''){return `<span class="badge ${cls}">${esc(text)}</span>`;}
function card(d){return `<article class="card"><div class="card-top"><span class="monogram" aria-hidden="true">${esc(d.mark)}</span><button class="save" data-save="${d.id}" aria-label="${state.saved.includes(d.id)?'Unsave':'Save'} ${esc(d.name)}" aria-pressed="${state.saved.includes(d.id)}">${state.saved.includes(d.id)?'★':'☆'}</button></div><div class="type">${esc(d.type)} · ${esc(d.category)}</div><h3><a href="${href(d)}">${esc(d.name)}</a></h3><p>${esc(d.summary)}</p><div class="badges">${badge(d.demo?'Fictional demo':d.source_status==='directory_notice_reviewed'?'Directory notice':'Source reviewed',d.demo?'warning':'positive')}${badge(d.license)}${badge(d.status,d.status==='Maintenance mode'||d.status==='Deprecated'?'warning':'')}</div><div class="source-line">${d.demo?'Demo owner':'Source'}: ${esc(d.owner)}<br>${esc(d.commercial)}</div><div class="card-bottom"><a href="${href(d)}">View details ↗</a><button data-compare="${d.id}" aria-pressed="${state.compare.includes(d.id)}">${state.compare.includes(d.id)?'Added ✓':'Compare +'}</button></div></article>`;}
function activeView(route){if(['products','product','service'].includes(route))return 'products';if(['technical','skills','skill','mcp-servers','mcp','plugins','plugin','repositories','repository'].includes(route))return 'technical';if(['marketplace','partners','partner'].includes(route))return 'marketplace';if(route==='item'){const d=D.find(d=>d.id===location.hash.split('/')[2]);return d?.type==='Partner Offer'?'marketplace':technical(d||{})?'technical':'products';}return 'discover';}
function shell(){document.body.dataset.brand=B.id;document.body.dataset.theme=B.id==='ai'?'dark':'light';$('#app').innerHTML=`<a class="skip" href="#main">Skip to content</a><header class="topbar"><a class="logo" href="#/discover">${B.logo}<small>${B.tagline}</small></a><nav class="toplinks" aria-label="Main navigation"><a href="#/categories">Categories</a><a href="#/saved">Saved <span id="savedCount"></span></a><a href="#/submit">Submit a resource ↗</a><a class="brand-switch" href="../${B.other}/index.html" id="brandSwitch">${B.otherName} ↗</a></nav></header><div class="ribbon"><nav class="views" aria-label="Four directory views">${views.map(([id,name],i)=>`<a href="#/${id}" data-view="${id}"><span aria-hidden="true">0${i+1} / </span>${name}</a>`).join('')}</nav><div class="controls"><label>Catalogue <select id="mode" aria-label="Catalogue data mode"><option value="reviewed">Reviewed source samples</option><option value="demo">Fictional demo data</option></select></label><label>Theme <select id="theme" aria-label="Color theme"><option value="light">Light</option><option value="dark">Dark</option><option value="contrast">High contrast</option></select></label></div></div><div class="prototype">HTML PROTOTYPE · ${B.id==='lawyer'?'Informational directory, not a law firm or legal advice.':'Third-party resources belong to their original creators.'} · No live submissions or installations.</div><main id="main" tabindex="-1"></main><footer class="footer"><div class="footer-grid"><div><a class="logo" href="#/discover">${B.logo}</a><p style="margin-top:18px">${B.disclaimer}</p></div><div><h3>Explore</h3>${[['discover','Discover'],['products','Products & services'],['technical','Skills, MCPs & repositories'],['marketplace','Marketplace'],['saved','Saved resources']].map(([id,t])=>`<a href="#/${id}">${t}</a>`).join('')}</div><div><h3>Trust & sources</h3>${[['how-listings-work','How listings work'],['provenance-and-licences','Provenance & licences'],['security-and-installation-safety','Installation safety'],['review','Local review queue'],['submit','Submit a resource']].map(([id,t])=>`<a href="#/${id}">${t}</a>`).join('')}</div><div><h3>The directory</h3>${[['about','About'],['contact','Contact'],['terms','Prototype terms'],['privacy','Privacy'],['sitemap','All pages']].map(([id,t])=>`<a href="#/${id}">${t}</a>`).join('')}</div></div><div class="footer-bottom">© 2026 ${B.name} · Original directory prototype. Listings do not transfer ownership, endorsement or rights. Source metadata checked 27 September 2026; security and compatibility are not audited.</div></footer><div id="comparisonBar" class="hidden"></div><div id="toast" class="toast hidden" role="status"></div><dialog id="compareDialog" aria-labelledby="compareTitle"><div class="dialog-top"><h2 id="compareTitle">Compare resources</h2><button id="closeCompare" aria-label="Close comparison">Close ×</button></div><div id="comparisonTable" class="table-scroll"></div></dialog>`;$('#theme').value=document.body.dataset.theme;$('#theme').onchange=e=>document.body.dataset.theme=e.target.value;$('#mode').onchange=e=>{state.mode=e.target.value;resetFilters();state.compare=[];render();};$('#closeCompare').onclick=()=>$('#compareDialog').close();$('#brandSwitch').onclick=e=>{const r=location.hash.split('/')[1]||'discover';e.currentTarget.href='../'+B.other+'/index.html#/'+(views.some(v=>v[0]===r)?r:'discover');};}
function resetFilters(){state.query='';state.category='All';state.types=[];state.savedOnly=false;}
function filtered(items){const q=state.query.toLowerCase();return items.filter(d=>(state.category==='All'||d.category===state.category)&&(!state.types.length||state.types.includes(d.type))&&(!state.savedOnly||state.saved.includes(d.id))&&(!q||[d.name,d.summary,d.category,d.owner,d.type,...d.tags].join(' ').toLowerCase().includes(q))).sort((a,b)=>state.sort==='az'?a.name.localeCompare(b.name):state.sort==='type'?a.type.localeCompare(b.type):a.order-b.order);}
function searchView(kind='discover',items=pool(),title){const allCategories=[...new Set(pool().map(d=>d.category))],types=[...new Set(items.map(d=>d.type))];return `${kind==='discover'?`<section class="hero"><div><div class="eyebrow">${B.eyebrow}</div><h1>${B.headline}</h1><p>${B.intro}</p></div><aside class="editorial"><small>From the editor / 001</small><h3>${B.editorTitle}</h3><p>${B.editorText}</p><a href="#/provenance-and-licences">Read our source standard ↗</a></aside></section>`:`<section class="market-head"><div class="eyebrow">The ${B.name} directory</div><h1>${esc(title||'Explore the catalogue.')}</h1><p>${kind==='technical'?'Look beyond the installation command. Understand the source, permissions and maintenance status first.':'Compare capabilities, ownership and commercial status before choosing a resource.'}</p></section>`}<form class="searchbox" id="searchForm"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search resources" placeholder="${B.search}" value="${esc(state.query)}"><button class="primary" type="submit">Search resources</button></form><div class="categories" aria-label="Filter by category">${['All',...allCategories].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${esc(c)}" aria-pressed="${state.category===c}">${esc(c)}</button>`).join('')}</div><div class="catalogue"><aside class="filters" id="filters" aria-label="Resource filters"><p class="filter-title">Refine your search</p><fieldset><legend>Resource type</legend>${types.map(t=>`<label><input type="checkbox" data-type="${esc(t)}" ${state.types.includes(t)?'checked':''}>${esc(t)}</label>`).join('')}</fieldset><fieldset><legend>Your collection</legend><label><input type="checkbox" id="savedOnly" ${state.savedOnly?'checked':''}>Saved resources</label></fieldset><button id="reset">Reset filters</button><p class="filter-note">${state.mode==='demo'?'All listings in this mode are fictional demonstrations.':'Source reviewed means the primary page was inspected. It is not a security or legal assessment.'}</p></aside><section aria-label="Resource results"><div class="results-head"><div><h2>${kind==='discover'?'The considered collection':esc(title||'Resources')}<span class="count" id="count"></span></h2></div><button class="filter-toggle secondary" id="filterToggle" aria-expanded="false" aria-controls="filters">Filters</button><select id="sort" aria-label="Sort resources"><option value="editorial">Editorial order</option><option value="az">Name: A–Z</option><option value="type">Resource type</option></select></div><div id="cards" class="cards"></div><div class="collection-band"><div><h3>${B.id==='lawyer'?'Good decisions start with good sources.':'Build with context. Not just components.'}</h3><p>Know a useful resource? Prepare a listing for editorial review.</p></div><a class="secondary" href="#/submit">Suggest a resource ↗</a></div></section></div>`;}
let currentItems=[];
function paintCards(){const result=filtered(currentItems);$('#cards').innerHTML=result.length?result.map(card).join(''):`<div class="empty"><h3>No matching resources.</h3><p>Try a broader search or reset your filters.</p><button class="secondary" data-reset>Clear filters</button></div>`;$('#count').textContent=result.length+' resources';wireCards();}
function wireSearch(items){currentItems=items;$('#sort').value=state.sort;$('#searchForm').onsubmit=e=>{e.preventDefault();state.query=$('#search').value;paintCards();};$('#search').oninput=e=>{state.query=e.target.value;paintCards();};$$('[data-category]').forEach(b=>b.onclick=()=>{state.category=b.dataset.category;$$('[data-category]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',c===b);});paintCards();});$$('[data-type]').forEach(c=>c.onchange=()=>{state.types=$$('[data-type]:checked').map(c=>c.dataset.type);paintCards();});$('#savedOnly').onchange=e=>{state.savedOnly=e.target.checked;paintCards();};$('#sort').onchange=e=>{state.sort=e.target.value;paintCards();};$('#reset').onclick=()=>{resetFilters();render();};$('#filterToggle').onclick=()=>{const open=$('#filters').classList.toggle('open');$('#filterToggle').setAttribute('aria-expanded',open);};paintCards();}
function wireCards(){$$('[data-save]').forEach(b=>b.onclick=()=>{const id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();b.setAttribute('aria-pressed',state.saved.includes(id));b.textContent=state.saved.includes(id)?'★':'☆';b.setAttribute('aria-label',(state.saved.includes(id)?'Unsave ':'Save ')+D.find(d=>d.id===id).name);$('#savedCount').textContent=state.saved.length||'';if(state.savedOnly&&$('#cards'))paintCards();});$$('[data-compare]').forEach(b=>b.onclick=()=>{const id=b.dataset.compare;if(state.compare.includes(id))state.compare=state.compare.filter(x=>x!==id);else if(state.compare.length<3)state.compare.push(id);else return toast('Compare up to three resources. Remove one to add another.');b.textContent=state.compare.includes(id)?'Added ✓':'Compare +';b.setAttribute('aria-pressed',state.compare.includes(id));paintCompare();});$$('[data-reset]').forEach(b=>b.onclick=()=>{resetFilters();render();});}
function paintCompare(){const bar=$('#comparisonBar');bar.className=state.compare.length?'compare-bar':'hidden';bar.innerHTML=`<span>${state.compare.length} of 3 resources selected</span><button id="showCompare">Compare</button><button id="clearCompare">Clear</button>`;$('#clearCompare').onclick=()=>{state.compare=[];render();};$('#showCompare').onclick=()=>{const ds=state.compare.map(id=>D.find(d=>d.id===id));$('#comparisonTable').innerHTML=`<table class="comparison"><thead><tr><th>Field</th>${ds.map(d=>`<th>${esc(d.name)}</th>`).join('')}</tr></thead><tbody>${[['type','Type'],['license','Licence'],['owner','Owner'],['commercial','Commercial status'],['status','Maintenance'],['risk','Permissions'],['compatibility','Compatibility']].map(([k,t])=>`<tr><th>${t}</th>${ds.map(d=>`<td>${esc(d[k])}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('#compareDialog').showModal();};}
function sourcePanel(d){return `<section class="panel"><h2>Source & ownership</h2><table class="metadata"><tbody>${[['Original maintainer',d.owner],['Ownership',d.demo?'Fictional demonstration':d.ownership],['Licence',d.license],['Commercial status',d.commercial],['Source check',d.demo?'Not applicable — fictional':'27 September 2026'],['Security review','Not audited'],['Maintenance',d.status],['Version / commit','Not pinned; source metadata only']].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}<tr><th>Primary source</th><td>${d.demo?'No real provider':external(d.source,'Original repository')}</td></tr><tr><th>Licence evidence</th><td>${d.demo?'No rights implied':external(d.licenseUrl,'Read source licence')||'Not verified'}</td></tr></tbody></table><p style="font-size:12px;margin-top:20px">Listed for discovery. This listing does not transfer ownership, endorsement, support responsibility or rights to use the resource. Review the original source and terms before use.</p></section>`;}
function detail(d){const tech=technical(d);return `<div class="breadcrumb"><a href="#/discover">Discover</a> / ${esc(d.category)} / ${esc(d.name)}</div><section class="detail-hero"><div><span class="monogram" aria-hidden="true">${esc(d.mark)}</span><div class="badges" style="margin-top:20px">${badge(d.type)}${badge(d.demo?'Fictional demonstration':d.source_status==='directory_notice_reviewed'?'Directory notice':'Source reviewed',d.demo?'warning':'positive')}${badge(d.status,d.status!=='Not assessed'?'warning':'')}</div><h1>${esc(d.name)}</h1><p>${esc(d.summary)}</p><div class="actions">${d.demo?'<a class="primary" href="#/submit">Prepare a review request</a>':external(d.source,'Visit original source','primary')}${external(d.docs||d.source,'Read documentation','secondary')}<button class="secondary" data-compare="${d.id}">${state.compare.includes(d.id)?'Added ✓':'Compare +'}</button><button class="save" data-save="${d.id}" aria-label="Save ${esc(d.name)}" aria-pressed="${state.saved.includes(d.id)}">${state.saved.includes(d.id)?'★':'☆'}</button></div></div><aside class="snapshot"><h3>At a glance</h3><dl><dt>Resource category</dt><dd>${esc(d.category)}</dd><dt>Owner / maintainer</dt><dd>${esc(d.owner)}</dd><dt>Licence</dt><dd>${esc(d.license)}</dd><dt>Commercial status</dt><dd>${esc(d.commercial)}</dd><dt>Editorial placement</dt><dd>${d.type==='Partner Offer'?'Demo placement; no commercial relationship':'Independent sample selection; not sponsored'}</dd></dl></aside></section>${d.status==='Deprecated'||d.status==='Maintenance mode'?`<div class="notice"><strong>${esc(d.status)}</strong><p>${esc(d.maintenanceNote||'Historical reference; not recommended for a new production dependency.')}</p></div>`:''}${d.demo?'<div class="notice">Fictional demonstration. No real provider, offer, price, sponsorship or availability is represented.</div>':''}<div class="detail-grid"><div><section class="panel"><h2>${tech?'What it connects':'What it helps you do'}</h2><p>${esc(d.description)}</p><ul>${d.capabilities.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></section>${tech?`<section class="panel"><h2>Technical context</h2><table class="metadata"><tbody>${[['Runtime',d.runtime],['Client compatibility',d.compatibility],['Permission scope',d.risk],['Data handling','Depends on deployment and connected services; inspect original documentation.'],['Installation status','Not installed or executed by this directory']].map(([k,v])=>`<tr><th>${k}</th><td>${esc(v)}</td></tr>`).join('')}</tbody></table><h3 style="margin-top:25px">Review record example</h3><p>A non-executable metadata template. This is not an installation command or working client configuration.</p><pre class="code" id="exampleConfig">${esc(JSON.stringify({resource:d.id,source:d.demo?'https://example.invalid/resource':d.source,execution_enabled:false,review_status:'pending',credentials:'NOT_INCLUDED'},null,2))}</pre><button id="copyConfig" class="secondary">Copy review example</button></section>`:`<section class="panel"><h2>Before you choose</h2><ul><li>Check scope, hosting and service terms with the original provider.</li><li>Review how sensitive information is stored and processed.</li><li>${B.id==='lawyer'?'Confirm jurisdiction and professional oversight before relying on any output.':'Test the workload and permission boundaries before connecting business systems.'}</li></ul><p><strong>Pricing:</strong> ${esc(d.commercial)}. This directory does not quote a purchase price or offer checkout.</p></section>`}${sourcePanel(d)}</div><aside><section class="panel"><h3>${B.id==='lawyer'?'Professional judgment comes first.':'Permission is part of the product.'}</h3><p>${B.disclaimer}</p><a href="#/security-and-installation-safety" class="secondary">Read the review guide</a></section><section class="panel"><h3>Found something incorrect?</h3><p>Prepare a correction with a source link. It stays in your local review queue until exported.</p><a class="secondary" href="#/report/${d.id}">Report this listing</a></section></aside></div><section class="related"><h2>Continue exploring</h2><div class="cards">${pool().filter(x=>x.id!==d.id).slice(0,3).map(card).join('')}</div></section>`;}
function marketplace(){const items=pool().filter(d=>d.type==='Partner Offer'||d.type==='Service');return `<section class="market-head"><div class="eyebrow">Relationships, made visible</div><h1>${B.id==='lawyer'?'The right expertise.<br>The right relationship.':'Build your company.<br>Choose your partners.'}</h1><p>Compare services with ownership, commercial relationships and review status in plain sight.</p></section><div class="transparency"><div><h3>Clear relationships</h3><p>Sponsorship, affiliate links and ownership must be declared on each listing.</p></div><div><h3>No paid ranking claims</h3><p>Sample order is editorial. There are no live placements or contracted partners.</p></div><div><h3>Direct to the source</h3><p>Commercial terms and service agreements belong to the provider.</p></div></div><div class="results-head"><h2>${state.mode==='demo'?'Demonstration offers':'Partner review status'}</h2><a href="#/submit" class="secondary">Suggest a service ↗</a></div><div class="cards">${items.length?items.map(card).join(''):`<div class="empty"><h3>No reviewed partners yet.</h3><p>Preview the marketplace structure using clearly fictional examples.</p><button class="primary" id="showDemo">Explore demo offers</button></div>`}</div><section class="panel" style="margin-top:30px"><h2>Compare before you commit</h2><p>Use Compare on up to three cards to inspect owners, licence status, permissions and commercial terms side by side.</p><a href="#/how-listings-work" class="secondary">How listings are reviewed ↗</a></section>`;}
const info={
 'about':['A directory with a point of view.',()=>B.id==='lawyer'?'Someone.lawyer brings legal research tools, document workflows and technical resources into one source-aware directory. It is not a law firm, and a listing does not create an attorney-client relationship.':'AI Company Market brings agents, workflows, Company Brain resources, MCP servers and integrations into one source-aware catalogue. Third-party work remains owned by its original creators.'],
 'how-listings-work':['Useful resources. Visible evidence.',()=> 'Every listing separates its original creator, resource type, licence, commercial status and review status. Source reviewed means the public primary page was inspected; it does not mean the resource is security-audited, endorsed, compatible with your setup or approved for production.'],
 'provenance-and-licences':['Credit belongs to the creator.',()=> 'We publish original editorial summaries and links. Source code, logos, screenshots, ratings and directory datasets are not republished here. A public repository does not automatically grant every right. Read the original licence and connected-service terms before use.'],
 'security-and-installation-safety':['Understand the permission boundary.',()=> 'Review read, write, network and command-execution permissions before installation. Inspect data destinations and dependency chains. Start in a test environment with minimal credentials. No resources in this prototype have been executed or security-audited.'],
 'terms':['Prototype terms & limitations.',()=> 'This is a local design prototype, not a live marketplace or contractual service. Demonstration offers are fictional. There is no checkout, installation or live professional referral. Production terms, operator details and applicable jurisdiction must be reviewed before publication.'],
 'privacy':['Your prototype data stays local.',()=> 'Search and filtering happen in this page. Saved resource IDs and review drafts are stored in this browser when storage is available. No forms are sent to a server. Exported files remain under your control. External source links open third-party websites with their own privacy practices.'],
 'legal-disclaimer':['A directory, not legal representation.',()=> 'Someone.lawyer does not provide legal advice or create an attorney-client relationship through its directory. No professional credentials, jurisdictional suitability or outcomes are certified by these sample listings. Consult an appropriately qualified professional for your matter.'],
 'mcp-safety':['Connection does not mean permission.',()=> 'A connector can expose powerful tools to an agent. Review authentication, available operations, network destinations and credential scope. This catalogue does not install MCP servers or certify their safety.'],
 'find-a-professional':['Find expertise with context.',()=> 'No professionals have been verified or onboarded in this prototype. Use the local review form to outline a service category for later editorial review. Do not include privileged, confidential or client-identifying information.'],
 'jurisdictions':['Jurisdiction is part of the question.',()=> 'The current legal research samples include US-focused resources and general document tooling. Their inclusion does not establish suitability in another jurisdiction. No jurisdiction-specific legal advice or professional licence verification is provided.']
};
function infoPage(id){const [title,body]=info[id];return `<section class="page-title"><div class="eyebrow">${B.name} / Directory standards</div><h1>${title}</h1></section><article class="prose"><p style="font-size:19px">${body()}</p><div class="panel"><h2>How the evidence is handled</h2><ol><li>Record the primary source and original maintainer.</li><li>Separate licence evidence from security and compatibility reviews.</li><li>Keep fictional offers outside reviewed source results.</li><li>Queue corrections for editorial review.</li><li>Publish only original summaries with visible source credit.</li></ol></div><div class="actions"><a class="primary" href="#/discover">Explore resources</a><a class="secondary" href="#/submit">Prepare a submission</a>${id==='privacy'?'<button class="secondary" id="clearLocal">Clear this brand’s local data</button>':''}</div></article>`;}
function formPage(kind,id){const report=kind==='report';return `<section class="page-title"><div class="eyebrow">Local editorial workflow</div><h1>${report?'Help improve this listing.':kind==='contact'?'Start a conversation.':'Bring a useful resource<br>into the picture.'}</h1><p>${report?'Record the issue and your evidence.':'Prepare a resource or enquiry for later editorial review.'} This form saves locally and can be exported. Nothing is sent.</p></section><form class="form panel" id="submission"><div class="two"><label>Resource or subject<input name="name" required maxlength="150" value="${esc(D.find(d=>d.id===id)?.name||'')}"></label><label>Resource type<select name="type"><option>Product</option><option>Service</option><option>Skill</option><option>MCP Server</option><option>Repository</option><option>Partner Offer</option><option>Correction</option><option>Enquiry</option></select></label></div><label>Original source URL<input name="source" type="url" placeholder="https://" ${kind==='contact'?'':'required'} value="${esc(D.find(d=>d.id===id)?.source||'')}"></label><label>Your relationship<select name="relationship"><option>Independent suggestion</option><option>Resource owner / maintainer</option><option>Service provider</option><option>Correction reporter</option></select></label><label>${report?'What should change?':'Summary and evidence'}<textarea name="notes" required maxlength="3000" placeholder="Describe the resource and include the evidence needed to review it. Do not include confidential information."></textarea></label><label><span><input type="checkbox" required> I understand this is a local draft, not a submitted or published listing.</span></label><button class="primary" type="submit">Save to local review queue</button></form>`;}
function review(){return `<section class="page-title"><div class="eyebrow">Editorial workspace / This browser only</div><h1>Review before publication.</h1><p>Local drafts await source, licence, commercial and security review. Nothing here is published.</p></section><div class="panel">${state.drafts.length?state.drafts.map(d=>`<div class="review-row"><strong>${esc(d.name)}</strong><small>${esc(d.type)} · Pending review · ${esc(d.created)}</small><p>${esc(d.notes)}</p>${external(d.source,'Source supplied by submitter')}</div>`).join(''):'<p>No drafts yet. Prepare a resource submission or report a listing.</p>'}<div class="actions"><a class="primary" href="#/submit">Add a draft</a><button class="secondary" id="exportQueue" ${state.drafts.length?'':'disabled'}>Export review queue ↓</button></div></div>`;}
function categoryPage(){return `<section class="page-title"><div class="eyebrow">A considered index</div><h1>Start with your work.</h1><p>Browse the categories in the selected catalogue mode.</p></section><div class="link-grid">${[...new Set(pool().map(d=>d.category))].map(c=>`<a class="link-tile" href="#/category/${encodeURIComponent(c)}">${esc(c)}<span>${pool().filter(d=>d.category===c).length} resources →</span></a>`).join('')}</div>`;}
function render(){let [,route='discover',id]=location.hash.split('/');if(!route)route='discover';const root=$('#main');$('#mode').value=state.mode;$('#savedCount').textContent=state.saved.length||'';$$('[data-view]').forEach(a=>{if(a.dataset.view===activeView(route))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});let items=null;const browseTypes={skills:['Skill'],'mcp-servers':['MCP Server'],plugins:['Plugin'],repositories:['Repository'],partners:['Partner Offer','Service'],agents:['Agent Package'],workflows:['Workflow Template'],integrations:['Connector','MCP Server'],'company-brain':['Repository','Workflow Template'],'ai-company-packages':['Agent Package'],'legal-workflows':['Workflow Template','Product']};if(['item','product','service','skill','mcp','plugin','repository','partner'].includes(route)){const d=D.find(x=>x.id===id);root.innerHTML=d?detail(d):'<section class="page-title"><h1>Resource not found.</h1><a class="primary" href="#/discover">Return to the directory</a></section>';if(d)document.title=d.name+' — '+B.name;}else if(route==='products'||route==='technical'){items=pool().filter(d=>route==='technical'?technical(d):!technical(d)&&d.type!=='Partner Offer');root.innerHTML=searchView(route,items,route==='technical'?'The building blocks.':'Products & services.');}else if(route==='marketplace'){root.innerHTML=marketplace();}else if(route==='categories'){root.innerHTML=categoryPage();}else if(route==='sitemap'){root.innerHTML=`<section class="page-title"><h1>Every route. One directory.</h1></section><div class="link-grid">${routes.map(r=>`<a class="link-tile" href="#/${r}">${esc(r.replaceAll('-',' '))}<span>Open page →</span></a>`).join('')}</div>`;}else if(info[route])root.innerHTML=infoPage(route);else if(['submit','contact','report'].includes(route))root.innerHTML=formPage(route,id);else if(route==='review')root.innerHTML=review();else if(route==='saved'){items=D.filter(d=>state.saved.includes(d.id));root.innerHTML=searchView('saved',items,'Your saved resources.');}else if(route==='category'){state.category=decodeURIComponent(id||'All');items=pool();root.innerHTML=searchView('category',items,state.category);}else if(browseTypes[route]){items=pool().filter(d=>browseTypes[route].includes(d.type));root.innerHTML=searchView(route,items,route.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase()));}else{if(route!=='discover'){root.innerHTML='<section class="page-title"><h1>This page is not in the directory.</h1><a href="#/discover" class="primary">Return to Discover</a></section>';}else{items=pool();root.innerHTML=searchView('discover',items);}}if(items)wireSearch(items);wireCards();paintCompare();if(!['item','product','service','skill','mcp','plugin','repository','partner'].includes(route))document.title=B.name+' — '+route.replaceAll('-',' ');if($('#showDemo'))$('#showDemo').onclick=()=>{state.mode='demo';resetFilters();render();};if($('#copyConfig'))$('#copyConfig').onclick=async()=>{try{await navigator.clipboard.writeText($('#exampleConfig').textContent);toast('Review example copied. It cannot install or execute a resource.');}catch(e){toast('Clipboard is unavailable. Select and copy the example text.');}};if($('#submission'))$('#submission').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(data.source&&!/^https?:\/\//i.test(data.source))return toast('Use an http or https source URL.');state.drafts.push({...data,id:Date.now().toString(36),status:'pending_review',created:new Date().toISOString(),brand:B.name});persist();location.hash='/review';toast('Draft saved locally. No information was sent.');};if($('#exportQueue'))$('#exportQueue').onclick=()=>download(B.id+'-review-queue.json',JSON.stringify(state.drafts,null,2));if($('#clearLocal'))$('#clearLocal').onclick=()=>{if(!$('#clearLocal').dataset.confirm){$('#clearLocal').dataset.confirm='yes';$('#clearLocal').textContent='Confirm: clear saved items and drafts';toast('Export any review drafts first. Select the confirmation button to clear this brand’s local data.');return;}state.saved=[];state.drafts=[];persist();render();toast('Local data cleared.');};}
const originalRender=render;render=function(){originalRender();const product=pool().find(d=>!technical(d)&&d.type!=='Partner Offer');const tech=pool().find(technical);if(product)document.querySelector('[data-view=products]').href='#/product/'+product.id;if(tech)document.querySelector('[data-view=technical]').href='#/repository/'+tech.id;};
shell();document.querySelector('.skip').onclick=e=>{e.preventDefault();document.querySelector('#main').focus();document.querySelector('#main').scrollIntoView();};window.addEventListener('hashchange',()=>{resetFilters();render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});render();
